  line SWIFT_OK "Swift を上げるワークフローを手で起動し、PR が仕様どおり出た（上げるものが無ければ、PR も Issue も立たない）"
  printf '\n- 起動した回: %s\n- PR: %s\n' "$(result SWIFT_RUN)" "$(result SWIFT_PR)"
  printf '\n残り（major の PR が残ること、落ちた PR の Issue、月曜の起動）は、10/5（月）の PR で確かめる。\n%s\n' "$FOOTER"
} > "$OUT_DIR/242.md"
post_comment 242 "$OUT_DIR/242.md"
note "#242 は月曜の確認が残るので、閉じません。"
pause "済んだら Enter"
write_env SWIFT_DONE "done"

else skip_section 3; fi

# ── 終わり ────────────────────────────────────────────────────────────────

stage "終わり"
for k in SENTRY_MAIL LOCKOUT_NORMAL LOCKOUT_SHOWN LOCKOUT_OFFLINE LOCKOUT_BUTTON LOCKOUT_RELEASED SWIFT_OK; do
  if [[ "$(result "$k")" == ng:* ]]; then
    warn "違ったところがあります。直すチケットを立てるよう、エージェントに頼んでください。"
